using Finance.Core;
using System.Data;
namespace Finance.Desktop;
internal partial class MainForm
{
    void Payroll(){using var f=new Form{Text="Monthly payroll • paid Sundays • absence-based salary",Width=1280,Height=780,StartPosition=FormStartPosition.CenterParent,Font=new("Segoe UI",10)};var bar=Bar();var period=new DateTimePicker{Format=DateTimePickerFormat.Custom,CustomFormat="MM-yyyy",ShowUpDown=true,Width=120};bar.Controls.Add(period);var tabs=new TabControl{Dock=DockStyle.Fill};var inputTab=new TabPage("1. Attendance and adjustments");var previewTab=new TabPage("2. Calculation review");var input=Ui.Grid();input.ReadOnly=false;input.SelectionMode=DataGridViewSelectionMode.CellSelect;var preview=Ui.Grid();inputTab.Controls.Add(input);previewTab.Controls.Add(preview);tabs.TabPages.AddRange([inputTab,previewTab]);DataTable data=new();Dictionary<string,(long Loan,long Employee)> loanColumns=[];List<PayrollResult>? calculation=null;
        void Load(){using var d=engine.Open();int year=period.Value.Year,month=period.Value.Month;int start=new DateOnly(year,month,1).DayNumber,end=new DateOnly(year,month,DateTime.DaysInMonth(year,month)).DayNumber;data=new DataTable();data.Columns.Add("EmployeeId",typeof(long));data.Columns.Add("Employee");data.Columns.Add("Monthly salary",typeof(decimal));foreach(var name in new[]{"Absent days","Advance deduction","OT","Bonus","Arrear","Other addition","Other deduction"})data.Columns.Add(name,typeof(decimal));data.Columns.Add("ESIC continuation",typeof(bool));loanColumns.Clear();var loans=d.Table("SELECT Id,Number,EmployeeId,EMI FROM Instrument WHERE Kind='Employee Loan' AND Status='Active' AND RecoveryDay<=@p0",end);foreach(DataRow r in loans.Rows){string col="Loan: "+Value.Text(r["Number"]);data.Columns.Add(col,typeof(decimal));loanColumns[col]=(Value.Long(r["Id"]),Value.Long(r["EmployeeId"]));}
            var employees=d.Table("SELECT * FROM Employee WHERE JoinDay<=@p0 AND (LeaveDay IS NULL OR LeaveDay>=@p1) AND (Active=1 OR LeaveDay IS NOT NULL)",end,start);foreach(DataRow e in employees.Rows){var row=data.NewRow();row["EmployeeId"]=e["Id"];row["Employee"]=e["Name"];row["Monthly salary"]=Value.Rupees(Value.Long(e["Salary"]));foreach(DataColumn c in data.Columns)if(c.DataType==typeof(decimal)&&c.ColumnName!="Monthly salary")row[c]=0m;row["ESIC continuation"]=false;foreach(DataRow loan in loans.Rows)if(Value.Long(loan["EmployeeId"])==Value.Long(e["Id"]))row["Loan: "+Value.Text(loan["Number"])]=Value.Rupees(Math.Min(Value.Long(loan["EMI"]),engine.Balance("ELOAN",employee:Value.Long(e["Id"]),instrument:Value.Long(loan["Id"]),through:end)));data.Rows.Add(row);}input.DataSource=data;foreach(var name in new[]{"EmployeeId","Employee","Monthly salary"})input.Columns[name].ReadOnly=true;input.Columns["EmployeeId"].Visible=false;foreach(DataGridViewRow row in input.Rows)foreach(var (col,ids) in loanColumns)if(Value.Long(row.Cells["EmployeeId"].Value)!=ids.Employee){row.Cells[col].ReadOnly=true;row.Cells[col].Style.BackColor=Color.LightGray;}calculation=null;preview.DataSource=null;}
        List<PayrollInput> Inputs(){input.EndEdit();f.BindingContext![data]!.EndCurrentEdit();return data.Rows.Cast<DataRow>().Select(r=>{long money(string c)=>Value.Money(Value.Dec(r[c]));var loans=new Dictionary<long,long>();foreach(var (col,ids) in loanColumns){long a=money(col);if(a!=0){Value.Require(ids.Employee==Value.Long(r["EmployeeId"]),"Loan recovery belongs to another employee.");loans[ids.Loan]=a;}}return new PayrollInput(Value.Long(r["EmployeeId"]),Value.Dec(r["Absent days"]),money("Advance deduction"),loans,money("OT"),money("Bonus"),money("Arrear"),money("Other addition"),money("Other deduction"),(bool)r["ESIC continuation"]);}).ToList();}
        void Calculate(){calculation=engine.Calculate(period.Value.Year,period.Value.Month,Inputs());var result=new DataTable();foreach(var name in new[]{"Employee","Calendar days","Sundays","Working days","Eligible days","Absent days","Payable days","Earned","Basic","Allowance","EPF wage","EPF","ESIC wage","ESIC","Advance opening","Advance recovery","Advance closing","Loan recovery","OT","Bonus","Arrear","Other addition","Other deduction","Net payable"})result.Columns.Add(name);foreach(var r in calculation)result.Rows.Add(r.Name,r.CalendarDays,r.Sundays,r.WorkingDays,r.EligibleDays,r.Absent,r.PayableDays,Value.Display(r.Earned),Value.Display(r.Basic),Value.Display(r.Allowance),Value.Display(r.EPFWage),Value.Display(r.EPF),Value.Display(r.ESICWage),Value.Display(r.ESIC),Value.Display(r.AdvanceOpening),Value.Display(r.Advance),Value.Display(r.AdvanceOpening-r.Advance),Value.Display(r.LoanRecovery),Value.Display(r.OT),Value.Display(r.Bonus),Value.Display(r.Arrear),Value.Display(r.OtherAddition),Value.Display(r.OtherDeduction),Value.Display(r.Net));preview.DataSource=result;tabs.SelectedTab=previewTab;}
        bar.Controls.Add(Ui.Button("Load employees",Load,145));bar.Controls.Add(Ui.Button("Calculate / review",Calculate,155));bar.Controls.Add(Ui.Button("Finalize payroll",()=>{Calculate();Confirm("Finalize this payroll and create salary/statutory payables? Bank will change only when salary is paid.",()=>{engine.FinalizePayroll(period.Value.Year,period.Value.Month,Inputs());f.DialogResult=DialogResult.OK;});},150));
        var help=new Label{Dock=DockStyle.Bottom,Height=62,Padding=new Padding(10),Text="Enter absent days and adjustments in INR. Sundays are paid and included in eligible calendar days.\nESIC continuation overrides the eligibility ceiling only for an employee already marked ESIC-applicable. Review the contribution-period position before using it."};f.Controls.Add(tabs);f.Controls.Add(bar);f.Controls.Add(help);Load();f.ShowDialog(this);
    }
}
